{"source":"def investigate(context, acquire):
    events = context.get('events', [])
    decoder = None
    count = 0
    status = 'open'
    for event in events:
        op = event.get('op')
        if op == 'feed':
            data = bytes(event.get('bytes', []))
            if decoder is None:
                decoder = __import__('codecs').getincrementaldecoder('utf-8')()
            text = decoder.decode(data, False)
            if text is None:
                status = 'error'
            else:
                count += len(text)
        elif op == 'finish':
            if decoder is None:
                decoder = __import__('codecs').getincrementaldecoder('utf-8')()
            text = decoder.decode(b'', True)
            if text is None:
                status = 'error'
            else:
                count += len(text)
                status = 'finished'
        elif op == 'reset':
            decoder = __import__('codecs').getincrementaldecoder('utf-8')()
            count = 0
            status = 'open'
    return {'count': count, 'status': status}
